SELECT , c.category_name FROM iot_product p LEFT JOIN iot_product_category c ON p.category_id = c.id AND c.del_flag = '0' WHERE p.del_flag = '0'
AND p.product_code LIKE CONCAT('%', #{product.productCode}, '%')
AND p.product_name LIKE CONCAT('%', #{product.productName}, '%')
AND p.category_id = #{product.categoryId}
AND p.product_type = #{product.productType}
AND p.status = #{product.status}
AND p.factory_code = #{product.factoryCode}
ORDER BY p.create_time DESC
